local a={map=function(b)if b[2]=="sender"then index_manager.addSender(index,b[3])end;if b[2]=="receiver"then index_manager.addReceiver(index,b[3],b[4])end end,list=function(b)print("Senders:")print(index_manager.listSenders(index))print("Receivers:")print(index_manager.listReceivers(index))end,search=function(b)local c=b[3]if b[2]=="sender"then local d=index_manager.searchSenders(index,c)if#d==0 then print("No senders found with name: "..c)else local e=false;for f,g in ipairs(d)do if g==c then e=true;print("Sender found: "..g)end end;if not e then print("No senders found with name: "..c)end end elseif b[2]=="receiver"then local h=index_manager.getReceiver(index,b[3])if h==nil then print("Receiver not found: "..b[3])else print("Receiver found: "..b[3])end else print("Unknown search type: "..b[2])end end,exit=function(b)print("Exiting...")return false end,help=function(b)print("Available commands:")print("map sender <name> - Add a sender to the index")print("map receiver <name> <address> - Add a receiver to the index")print("list - List all senders and receivers")print("search sender <name> - Search for a sender by name")print("search receiver <address> - Search for a receiver by address")print("exit - Exit the program")end}return a
